def cone(start):
    seen=set(); stack=[start]
    while stack:
        c=stack.pop()
        if c in seen: continue
        seen.add(c)
        for i in imports.get(c,[]):
            if i.startswith("AlgebraicJacobian") and i not in seen:
                stack.append(i)
